mapper.insert:
INSERT INTO job_run (
  job_name, workspace_id, status, started_at, finished_at, detail
) VALUES (
  #{jobName}, #{workspaceId}, #{status}, #{startedAt}, #{finishedAt}, #{detail}
)

mapper.delete:
DELETE FROM job_run
WHERE job_name = #{jobName}

    AND workspace_id IS NULL
    AND workspace_id = #{workspaceId}

  AND id NOT IN (
    SELECT id FROM (
      SELECT id
      FROM job_run
      WHERE job_name = #{jobName}

          AND workspace_id IS NULL
          AND workspace_id = #{workspaceId}

      ORDER BY started_at DESC, id DESC
      LIMIT #{keepCount}
    ) AS keep_rows
  )
